import {freshJob,changeVehicle,attachSelection} from './jobs.js';
import {analyzeVin} from './vin.js';
export function createCounter(api){
 const {esc,panel,toast,copy,download,read,save}=api,$=s=>document.querySelector(s);
 let lookup=null;
 const saveJob=j=>api.writeJob(j);
 function addPart(id,quiet=false){const p=api.getIndex().parts.find(p=>p.id===id);if(!p)return;const j=structuredClone(api.getJob());const row=j.rows.find(r=>r.id===id);if(row){if(!quiet)row.qty=Math.min(999,row.qty+1);}else j.rows.push({id,name:p.name,bases:p.codes,qty:1,note:''});if(saveJob(j)&&!quiet)toast('Added to '+(j.job||'current job'));return j.rows.find(r=>r.id===id);}
 function openJobs(){const book=api.getJobs();panel(`<span class="dialog-category">JOB DESK</span><h2>Every vehicle. Its own workspace.</h2><p>Switch between counter calls without losing the VIN, notes or selected service numbers.</p><button class="primary" id="newJob">＋ New job</button><div class="job-list">${book.items.map(j=>`<button class="job-card ${book.activeId===j.id?'current':''}" data-switch-job="${esc(j.id)}"><span class="job-avatar">${j.status==='Done'?'✓':'↗'}</span><span><strong>${esc(j.job||'Untitled job')}</strong><small>${esc(j.vehicle||j.vin||'Vehicle not set')}</small><small>${j.rows.length} part families · ${j.rows.filter(r=>r.selection&&!r.selection.stale).length} selected service numbers</small></span><span class="job-status">${esc(j.status||'Open')}</span></button>`).join('')}</div>`);
  $('#newJob').onclick=()=>{const j=freshJob();if(api.writeJobs({activeId:j.id,items:[j,...book.items]}))openJob();};
  document.querySelectorAll('[data-switch-job]').forEach(b=>b.onclick=()=>{if(api.writeJobs({...book,activeId:b.dataset.switchJob}))openJob();});
 }
 function openJob(){const j=api.getJob();panel(`<span class="dialog-category">CURRENT JOB</span><h2>${esc(j.job||'Build the next lookup.')}</h2><div class="tools-actions"><button class="secondary" id="allJobs">All jobs (${api.getJobs().items.length})</button><button class="secondary" id="jobDecode">VIN Decoder</button><button class="secondary" id="finishJob">${j.status==='Done'?'Reopen job':'Mark done'}</button></div><div class="job-fields"><label>Job / RO<input id="jobName" maxlength="200" value="${esc(j.job)}" placeholder="RO, stock number or counter call"></label><label>VIN / vehicle note<input id="jobVin" maxlength="200" value="${esc(j.vin)}" placeholder="Paste the 17-character VIN"></label></div>${j.vehicle?`<p class="vehicle-summary">${esc(j.vehicle)}</p>`:''}<p class="micro">Changing the VIN marks earlier service selections for rechecking.</p><div id="jobRows">${j.rows.map((r,i)=>`<section class="job-row"><div class="job-row-title"><strong>${esc(r.name)}</strong><button class="text-button" data-job-remove="${i}" aria-label="Remove ${esc(r.name)}">Remove</button></div><div class="job-bases">${r.bases.slice(0,10).map(esc).join(' · ')}${r.bases.length>10?' + more':''}</div>${r.selection?`<div class="selection ${r.selection.stale?'stale':''}"><span>${r.selection.stale?'VEHICLE CHANGED · RECHECK':'EMPLOYEE SELECTED'}</span><strong>${esc(r.selection.serviceNumber)}</strong><small>${esc(r.selection.context||r.selection.description||'')}</small><small>${esc(r.selection.source)} · ${esc((r.selection.selectedAt||'').slice(0,10))}</small></div>`:'<p class="pending-selection">Service number not selected</p>'}<div class="job-inputs"><label>Qty<input type="number" min="1" max="999" data-job-qty="${i}" value="${r.qty}"></label><label>Counter note<input data-job-note2="${i}" maxlength="1000" value="${esc(r.note)}" placeholder="Bin, position, reminder…"></label></div><div class="tools-actions"><button class="primary" data-job-epc="${esc(r.id)}">Find service part ↗</button>${r.selection?`<button class="secondary" data-copy-part="${esc(r.selection.serviceNumber)}">Copy number</button>`:''}</div></section>`).join('')||'<div class="job-empty">Search for a part, then add it to this job.</div>'}</div><div class="tools-actions"><button class="secondary" id="copyJob">Copy job</button><button class="secondary" id="exportJob">Export CSV</button><button class="secondary" id="printJob">Print job</button></div>`);
  $('#allJobs').onclick=openJobs;$('#jobDecode').onclick=api.showVin;
  $('#finishJob').onclick=()=>{if(saveJob({...api.getJob(),status:j.status==='Done'?'Open':'Done'}))openJob();};
  $('#jobName').oninput=e=>saveJob({...api.getJob(),job:e.target.value});
  $('#jobVin').oninput=e=>{if(saveJob(changeVehicle(api.getJob(),e.target.value.trim().toUpperCase()))){document.querySelectorAll('#jobRows .selection').forEach(s=>{s.classList.add('stale');s.querySelector('span').textContent='VEHICLE CHANGED · RECHECK';});}};
  $('#jobRows').oninput=e=>{const next=structuredClone(api.getJob());if(e.target.hasAttribute('data-job-qty')){const q=Number(e.target.value);if(!Number.isInteger(q)||q<1||q>999)return;next.rows[+e.target.dataset.jobQty].qty=q;}else if(e.target.hasAttribute('data-job-note2'))next.rows[+e.target.dataset.jobNote2].note=e.target.value;else return;saveJob(next);};
  $('#jobRows').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.jobEpc)openLookup(b.dataset.jobEpc);if(b.dataset.copyPart)copy(b.dataset.copyPart);if(b.hasAttribute('data-job-remove')){const next=structuredClone(api.getJob());next.rows.splice(+b.dataset.jobRemove,1);if(saveJob(next))openJob();}};
  const summary=()=>{const j=api.getJob();return [j.job,j.vehicle||'',j.vin,...j.rows.map(r=>`${r.qty} × ${r.name}\n${r.selection?(r.selection.stale?'RECHECK: ':'Selected: ')+r.selection.serviceNumber:'Base candidates: '+r.bases.join(', ')}${r.selection?.context?'\n'+r.selection.context:''}${r.note?'\n'+r.note:''}`),'Selections are employee-reviewed references. Check current EPC restrictions and supersessions.'].filter(Boolean).join('\n\n');};
  $('#copyJob').onclick=()=>copy(summary());$('#exportJob').onclick=()=>{const j=api.getJob(),cell=x=>'"'+String(x??'').replace(/^[=+@-]/,"'$&").replace(/"/g,'""')+'"';download('LB-Smith-job.csv',['job,vin,quantity,part,bases,service_number,selection_status,note',...j.rows.map(r=>[j.job,j.vin,r.qty,r.name,r.bases.join(';'),r.selection?.serviceNumber||'',r.selection?(r.selection.stale?'recheck':'employee selected'):'not selected',r.note].map(cell).join(','))].join('\r\n'));};
  $('#printJob').onclick=()=>{if(typeof window.PartsNative?.printJob==='function')window.PartsNative.printJob(summary());else{let area=document.querySelector('#printArea');if(!area){area=document.createElement('pre');area.id='printArea';document.body.append(area);}area.textContent=summary();window.print();}};
 }
 function openLookup(rowId){const row=api.getJob().rows.find(r=>r.id===rowId)||addPart(rowId,true);if(!row)return;const j=api.getJob();lookup={jobId:j.id,rowId};const bases=row.bases.map(number=>({number,label:api.getIndex().byBase.get(number)?.bases.find(b=>b.number===number)?.label||''}));
  panel(`<span class="dialog-category">VIN → SERVICE PART</span><h2>${esc(row.name)}</h2><div class="lookup-steps"><span>01 · Choose base</span><span>02 · Open EPC</span><span>03 · Save selection</span></div><label class="note-label" for="lookupVin">VIN</label><div class="detail-filter"><input id="lookupVin" maxlength="30" value="${esc(j.vin)}" placeholder="17-character VIN" autocapitalize="characters"></div><label class="note-label" for="lookupBase">Base number</label><select class="wide-select" id="lookupBase">${bases.map(b=>`<option value="${b.number}">${b.number}${b.label?' · '+esc(b.label):''}</option>`).join('')}</select><p id="lookupStatus" role="status">The VIN and base identify candidates. Choose the correct position and application in EPC.</p><button class="primary wide" id="launchEpc">${typeof window.PartsNative?.openEpc==='function'?'Open assisted EPC lookup ↗':'Open Snap-on EPC ↗'}</button><p class="micro">${typeof window.PartsNative?.openEpc==='function'?'Sign into your own Snap-on account in the catalog view. Tap Load VIN, Search, then Review parts after opening the correct illustration. Your existing desktop login does not transfer to your phone.':'In this browser version, open your signed-in EPC tab, enter the VIN and base, then record your selected number below. Android includes an assisted catalog view.'}</p><div class="tools-actions"><button class="secondary" id="copyLookupVin">Copy VIN</button><button class="secondary" id="copyLookupBase">Copy base</button></div><details class="manual-selection"><summary>Record a number reviewed in EPC</summary><form id="manualPart"><label class="note-label">Full service number<input id="serviceNumber" required maxlength="40" placeholder="Full number from EPC"></label><label class="note-label">Position / application<input id="serviceContext" required maxlength="500" placeholder="Front, rear, equipment or restrictions"></label><label class="confirm-line"><input type="checkbox" required> I checked this number against the VIN and application in EPC.</label><button class="primary" type="submit">Save to job</button></form></details>`);
  const getRequest=()=>{const a=analyzeVin($('#lookupVin').value);if(!a.valid)throw Error(a.error);const book=api.getJobs(),job=book.items.find(x=>x.id===lookup.jobId);if(!job)throw Error('This job no longer exists.');if(job.vin!==a.vin&&!saveJob(changeVehicle(job,a.vin)))throw Error('Could not save the VIN.');return {vin:a.vin,base:$('#lookupBase').value};};
  $('#copyLookupVin').onclick=()=>copy($('#lookupVin').value.trim().toUpperCase());$('#copyLookupBase').onclick=()=>copy($('#lookupBase').value);
  $('#launchEpc').onclick=()=>{try{const r=getRequest();if(typeof window.PartsNative?.openEpc==='function'){const id=lookup.jobId+'|'+lookup.rowId+'|'+Date.now();if(!save('epc-pending',{id,...lookup,vin:r.vin,base:r.base}))return;window.PartsNative.openEpc(JSON.stringify({vin:r.vin,bases:[r.base,...row.bases.filter(b=>b!==r.base)].slice(0,100),requestId:id}));}else window.open('https://snaponepc.com/epc/','_blank','noopener');}catch(e){$('#lookupStatus').textContent=e.message;}};
  $('#manualPart').onsubmit=e=>{e.preventDefault();try{const r=getRequest(),next=attachSelection(api.getJob(),rowId,{...r,serviceNumber:$('#serviceNumber').value.trim().toUpperCase(),context:$('#serviceContext').value.trim(),source:'Manual EPC review — employee entered'});if(saveJob(next)){toast('Service number saved to job');openJob();}}catch(e){$('#lookupStatus').textContent=e.message;}};
 }
 function receiveEpc(){if(typeof window.PartsNative?.getEpcResult!=='function')return;const raw=window.PartsNative.getEpcResult();if(!raw)return;try{const r=JSON.parse(raw),pending=read('epc-pending',null);if(!pending||r.requestId!==pending.id)throw Error('This EPC result belongs to an earlier lookup. Start a new lookup.');const book=api.getJobs(),job=book.items.find(j=>j.id===pending.jobId);if(!job)throw Error('The lookup job could not be found.');const next=attachSelection(job,pending.rowId,r);if(!api.writeJobs({activeId:job.id,items:book.items.map(j=>j.id===job.id?next:j)}))return;window.PartsNative.acknowledgeEpcResult();save('epc-pending',null);toast('EPC selection saved');openJob();}catch(e){toast(e.message);window.PartsNative.acknowledgeEpcResult();}}
 window.addEventListener('parts-epc-result',receiveEpc);
 return {openJobs,openJob,addPart,openLookup,receiveEpc};
}
